.news-heading{display:flex;justify-content:space-between;gap:1rem;align-items:center}.news-heading h2{font-family:Georgia,serif;font-size:1.65rem;margin:0}.news-heading p{color:var(--muted);margin:.25rem 0 0;font-size:.86rem}.news-actions{display:flex;gap:.45rem;flex-wrap:wrap}.news-actions .btn{border-radius:999px}
.news-workspace{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(290px,.75fr);gap:1rem;margin-top:1rem}.preview-shell{background:#e9e5dc;border-radius:14px;padding:.8rem}.preview-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:.6rem;font-size:.72rem;text-transform:uppercase;letter-spacing:.08em;color:#596568}.preview-top strong{color:var(--teal)}.preview-frame{background:#fffdf9;border-radius:10px;padding:1.1rem;min-height:400px;overflow:hidden}.preview-frame.mobile{max-width:390px;margin:auto}.public-mast{border-bottom:2px solid var(--ink);padding-bottom:.55rem;margin-bottom:1rem;display:flex;justify-content:space-between;align-items:end}.public-mast b{font-family:Georgia,serif;font-size:1.35rem}.public-mast small{color:var(--muted)}
.hero-story,.secondary-story,.archive-story{cursor:pointer;outline:0}.hero-story{display:grid;grid-template-columns:1.12fr .88fr;gap:1rem;padding-bottom:1rem;border-bottom:1px solid #ddd8ce}.hero-story.no-image{grid-template-columns:1fr}.story-image{width:100%;height:100%;min-height:130px;object-fit:cover;border-radius:5px;background:#e5e0d6}.hero-story h3{font-family:Georgia,serif;font-size:clamp(1.25rem,2.2vw,2rem);line-height:1.08;margin:.25rem 0}.story-kicker{font-size:.68rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--coral)}.story-excerpt{font-size:.82rem;line-height:1.5;color:#516064;white-space:pre-line}.story-meta{color:#7c8788;font-size:.68rem}.secondary-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.8rem;margin:1rem 0;border-bottom:1px solid #ddd8ce;padding-bottom:1rem}.secondary-story{padding:.25rem}.secondary-story.no-image{padding-top:.1rem}.secondary-story h4{font-family:Georgia,serif;font-size:1rem;line-height:1.15;margin:.25rem 0}.secondary-story .story-image{height:72px;min-height:0;margin-bottom:.4rem}.archive-label{font-size:.65rem;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);font-weight:700}.archive-story{display:flex;gap:.65rem;padding:.65rem 0;border-bottom:1px solid #eee9e1}.archive-story.no-image{display:block}.archive-story h5{font-family:Georgia,serif;margin:0;font-size:.9rem}.archive-story .story-image{width:54px;height:44px;min-height:0;flex:none}.selected-story{box-shadow:inset 3px 0 var(--coral);padding-left:.55rem}.story-focus:focus-visible{box-shadow:0 0 0 3px #e5a28e!important}.reason{background:#eef4f1;color:#245553;border-radius:8px;padding:.65rem;font-size:.78rem;margin-top:.7rem}.management{background:#fff;border:1px solid #e3dfd5;border-radius:12px;padding:.8rem}.management h3{font-size:.9rem;margin:.1rem 0 .6rem}.manage-item{display:flex;align-items:center;flex-wrap:wrap;gap:.5rem;border-top:1px solid #eee;padding:.6rem .1rem;font-size:.78rem}.manage-item button{border:0;background:transparent;color:var(--teal)}.manage-item-title{flex:1 1 150px;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.badge-news{font-size:.65rem;border:1px solid #cbd8d2;padding:.18rem .4rem;border-radius:999px;color:#38605d;background:#f1f7f3}.news-empty{text-align:center;color:var(--muted);padding:3rem 1rem}.news-control-room button:focus-visible,.news-control-room input:focus-visible,.news-control-room select:focus-visible,.news-control-room textarea:focus-visible{outline:3px solid #e5a28e;outline-offset:2px}.news-control-room .modal-content{border:0;border-radius:14px}.news-control-room .form-label{font-size:.78rem;font-weight:700}.news-control-room textarea{min-height:130px}.news-control-room .modal-dialog{max-width:680px}
.preview-frame.mobile{width:100%;max-width:390px;overflow-x:hidden}.preview-frame.mobile .public-mast{align-items:flex-start;flex-direction:column;gap:.2rem}.preview-frame.mobile .hero-story{grid-template-columns:1fr;min-width:0}.preview-frame.mobile .secondary-grid{grid-template-columns:1fr;min-width:0}.preview-frame.mobile .story-focus,.preview-frame.mobile .story-focus>div{min-width:0;max-width:100%;overflow-wrap:anywhere}.preview-frame.mobile .story-meta{display:block;overflow-wrap:anywhere;word-break:break-word}.preview-frame.mobile .archive-story{gap:.5rem;padding:.55rem 0}.preview-frame.mobile .archive-story h5{overflow-wrap:anywhere}
.story-body{min-width:0}.archive-story .story-body{flex:1}.story-content{cursor:pointer}.story-content:focus-visible{box-shadow:0 0 0 3px #e5a28e;outline:0;border-radius:3px}.announcement-image-editor{border:1px solid #e3dfd5;border-radius:12px;overflow:hidden;background:#f5f3ee}.announcement-image-preview{display:block;width:100%;height:230px;object-fit:cover;background:#e8e3da}.announcement-image-placeholder{height:150px;display:flex;align-items:center;justify-content:center;color:var(--muted);font-size:.82rem}.announcement-image-url{padding:.8rem;background:#fff;border-top:1px solid #e3dfd5}
@media(max-width:800px){.news-workspace{grid-template-columns:1fr}.hero-story{grid-template-columns:1fr}.secondary-grid{grid-template-columns:1fr}.preview-frame{padding:.8rem}.news-heading{align-items:flex-start;flex-direction:column}}@media(prefers-reduced-motion:reduce){.news-control-room *{transition:none!important}}
}
.news-control-room-modal .modal-content{border:0;border-radius:14px}.news-control-room-modal .form-label{font-size:.78rem;font-weight:700}.news-control-room-modal textarea{min-height:130px}.news-control-room-modal .modal-dialog{max-width:680px}
