<div class="row g-2"><div class="col-md-5"><label class="form-label" for="announcement-type">Type</label><select class="form-select" id="announcement-type"><option value="news">Nyhet</option><option value="event">Arrangement</option><option value="info">Informasjon</option><option value="promotion">Aktuelt</option><option value="urgent">Viktig melding</option></select></div><div class="col-md-7 d-flex align-items-end"><div class="form-check mb-2"><input class="form-check-input" type="checkbox" id="announcement-is-pinned"><label class="form-check-label" for="announcement-is-pinned">Fest øverst</label></div></div></div>
<div class="row g-2 mt-2"><div class="col-md-6"><label class="form-label" for="announcement-publish-at">Publiseres</label><input type="datetime-local" class="form-control" id="announcement-publish-at"></div><div class="col-md-6"><label class="form-label" for="announcement-expire-at">Utløper</label><input type="datetime-local" class="form-control" id="announcement-expire-at"></div></div>
<div class="form-check form-switch mt-3"><input class="form-check-input" type="checkbox" id="announcement-product-toggle"><label class="form-check-label" for="announcement-product-toggle">Knytt til produkt</label></div><div id="product-section" class="mt-2" hidden><select class="form-select mb-2" id="announcement-product-id"><option value="">Velg produkt</option></select><div class="row g-2"><div class="col-4"><input type="number" class="form-control" id="announcement-discount" min="0" max="100" placeholder="Rabatt %"></div><div class="col-4"><input type="number" class="form-control" id="announcement-max-qty" min="1" placeholder="Maks antall"></div><div class="col-4"><input type="date" class="form-control" id="announcement-product-expiry"></div></div></div>
<div class="border-top mt-4 pt-3"><label class="form-label" for="announcement-priority">Prioritet</label><select class="form-select" id="announcement-priority" aria-describedby="announcement-priority-help"><option value="1">1</option><option value="2">2</option><option value="3">3</option><option value="4">4</option><option value="5" selected>5</option><option value="6">6</option><option value="7">7</option><option value="8">8</option><option value="9">9</option><option value="10">10</option></select><small id="announcement-priority-help" class="text-muted">1 høyest · 10 lavest</small></div>
<div class="mt-4"><label class="form-label">Bilde i simuleringen</label><div class="announcement-image-editor"><img id="announcement-image-preview" class="announcement-image-preview" alt="Forhåndsvisning av nyhetsbildet" hidden><div id="announcement-image-placeholder" class="announcement-image-placeholder">Ingen gyldig bilde-URL</div><div class="announcement-image-url"><label class="form-label" for="announcement-image-url">Bilde-URL</label><input type="url" class="form-control" id="announcement-image-url" placeholder="https://…"></div></div></div>
</div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal" id="cancelAnnouncement">Avbryt</button><button type="button" class="btn btn-outline-secondary" id="saveDraftButton">Lagre som kladd</button><button type="button" class="btn btn-primary" id="publishButton">Publiser</button></div></form></div></div></div>
<script src="/assets/announcement_ranking.js"></script>
<script>
(() => {
const types={event:'Arrangement',info:'Informasjon',news:'Nyhet',promotion:'Aktuelt',urgent:'Viktig melding'},legacyPriority={urgent:1,high:3,normal:5,low:8},priorityValue=value=>{let n=Number(value);return Number.isInteger(n)&&n>=1&&n<=10?n:(legacyPriority[String(value)]||5)};let announcements=[],previewDraft=null,selectedId=null,previewMode='desktop',lastTrigger=null,publishIntent=false,simulatePublished=true,previewEffectivePublishAt=null,editRevision=0,loadRevision=0,saveBusy=false,imagePreviewUrl='',imagePreviewFailed=false;
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), norm=s=>String(s??'').replace(/\r\n?/g,'\n'), val=id=>$(id).value;
 $('announcementModal').classList.add('news-control-room-modal');
const previewSwitch=document.createElement('div');previewSwitch.className='form-check form-switch mt-3';previewSwitch.innerHTML='<input class="form-check-input" type="checkbox" id="simulate-published"><label class="form-check-label" for="simulate-published">Simuler som publisert</label>';$('announcement-product-toggle').closest('.form-check').before(previewSwitch);
const active=a=>!!a?.is_published&&(!a.publish_at||new Date(a.publish_at)<=new Date())&&(!a.expire_at||new Date(a.expire_at)>new Date());
const excerpt=(s,n)=>{s=norm(s).trim();if(s.length<=n)return s;return s.slice(0,n).replace(/\s+\S*$/,'').trim()+'…'};
function allRows(){let rows=announcements.map(a=>previewDraft&&String(a.id)===String(previewDraft.id)?previewDraft:a);if(previewDraft&&!announcements.some(a=>String(a.id)===String(previewDraft.id)))rows.push(previewDraft);return rows}
 function ranked(){return AnnouncementRanking(allRows().filter(active))}
function date(s){return s?new Date(s).toLocaleDateString('nb-NO',{day:'numeric',month:'short',year:'numeric'}):'Ikke datert'}
function image(a){return a.image_url?`<img class="story-image" src="${esc(a.image_url)}" alt="" loading="lazy">`:''}
 function story(a,place){let tag=types[a.announcement_type]||'Kunngjøring',heading=place==='hero'?'h3':place==='secondary'?'h4':'h5',noImage=a.image_url?'':' no-image',id=esc(a.id);return `<article class="${place}-story${noImage}${String(a.id)===String(selectedId)?' selected-story':''}" data-story-id="${id}">${image(a)}<div class="story-body"><div class="story-content" tabindex="0" role="button" aria-label="Rediger ${esc(a.title)}"><span class="story-kicker">${esc(tag)}${a.is_pinned?' · Festet':''}</span><${heading}>${esc(a.title)}</${heading}>${place!=='archive'?`<p class="story-excerpt">${esc(excerpt(a.content,place==='hero'?210:105))}</p>`:''}<span class="story-meta">${esc(date(a.publish_at))}${a.product?.name?' · Produkt: '+esc(a.product.name):''}</span></div></div></article>`}
 function reasonFor(a,rows){if(!a)return '';if(!a.is_published)return 'Denne saken er en kladd og vises ikke for leserne.';if(a.publish_at&&new Date(a.publish_at)>new Date())return 'Denne saken er planlagt og vises ikke før publiseringstidspunktet.';if(a.expire_at&&new Date(a.expire_at)<=new Date())return 'Denne saken er utløpt og vises ikke lenger.';let i=rows.findIndex(x=>String(x.id)===String(a.id));return i===0?(a.is_pinned?'Denne saken blir hovedsak fordi den er festet.':`Denne saken blir hovedsak med prioritet ${priorityValue(a.priority)}.`):(i<5?`Denne saken blir sekundærsak med prioritet ${priorityValue(a.priority)}.`:`Denne saken ligger i arkivet fordi ${i} saker rangeres høyere.`)}
 function renderPreview(){let rows=ranked(),p=$('news-preview');p.innerHTML=rows.length?`<header class="public-mast"><b>Nyheter</b><small>Simulert offentlig visning · trykk på en sak for å redigere</small></header><div class="hero-wrap">${story(rows[0],'hero')}</div>${rows.length>1?`<div class="secondary-grid">${rows.slice(1,5).map(a=>story(a,'secondary')).join('')}</div>`:''}${rows.length>5?`<div class="archive-label">Arkiv</div>${rows.slice(5).map(a=>story(a,'archive')).join('')}`:''}`:'<div class="news-empty"><strong>Ingen aktive saker</strong><br><small>Publiserte saker innenfor publiseringstid vises her.</small></div>';p.querySelectorAll('img.story-image').forEach(img=>img.addEventListener('error',()=>{let card=img.closest('[data-story-id]');img.remove();card?.classList.add('no-image')}));p.querySelectorAll('.story-content').forEach(el=>{el.addEventListener('click',()=>edit(el.closest('[data-story-id]').dataset.storyId));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();edit(el.closest('[data-story-id]').dataset.storyId)}})});let selected=previewDraft&&String(previewDraft.id)===String(selectedId)?previewDraft:announcements.find(a=>String(a.id)===String(selectedId));let box=$('selected-reason');box.textContent=selected?reasonFor(selected,rows):'';box.hidden=!selected}
 function renderManagement(){let f=$('news-filter').value,now=new Date(),rows=announcements.filter(a=>f==='all'||f==='draft'&&!a.is_published||f==='scheduled'&&a.is_published&&a.publish_at&&new Date(a.publish_at)>now||f==='published'&&active(a));$('news-management').innerHTML=rows.length?rows.map(a=>`<div class="manage-item"><span class="manage-item-title" title="${esc(a.title)}">${a.is_pinned?'▸ ':''}${esc(a.title)}</span><span class="badge-news">${Number(a.clicks)||0} klikk</span><span class="badge-news">Prioritet ${priorityValue(a.priority)}</span><button type="button" data-action="edit" data-id="${esc(a.id)}">Rediger</button><button type="button" data-action="pin" data-id="${esc(a.id)}">${a.is_pinned?'Løsne':'Fest'}</button><button type="button" data-action="publish" data-id="${esc(a.id)}">${a.is_published?'Skjul':'Publiser'}</button><button type="button" data-action="delete" data-id="${esc(a.id)}">Slett</button></div>`).join(''):'<div class="news-empty py-4">Ingen saker i dette filteret.</div>'}
function render(){ $('news-preview').classList.toggle('mobile',previewMode==='mobile');$('desktopView').classList.toggle('active',previewMode==='desktop');$('mobileView').classList.toggle('active',previewMode==='mobile');renderPreview();renderManagement()}
function productFromForm(){if(!$('announcement-product-toggle').checked)return null;let id=val('announcement-product-id');if(!id)return null;let option=$('announcement-product-id').selectedOptions[0];return {output_product_id:id,name:option?.textContent||'',discount_percent:Number(val('announcement-discount'))||0,max_quantity:val('announcement-max-qty')?Number(val('announcement-max-qty')):null,expiry_date:val('announcement-product-expiry')||null}}
function localSqlNow(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')}
function effectivePublishAt(){return val('announcement-publish-at')||previewEffectivePublishAt}
 function updateImagePreview(){let url=val('announcement-image-url').trim(),img=$('announcement-image-preview'),placeholder=$('announcement-image-placeholder'),valid=false;try{let parsed=new URL(url);valid=parsed.protocol==='http:'||parsed.protocol==='https:'}catch(e){}if(!valid){imagePreviewUrl='';imagePreviewFailed=false;img.hidden=true;placeholder.hidden=false;img.removeAttribute('src');return}if(url!==imagePreviewUrl){imagePreviewUrl=url;imagePreviewFailed=false;img.src=url}img.hidden=imagePreviewFailed;placeholder.hidden=!imagePreviewFailed}
 function syncDraft(){let id=val('announcement-id')||'draft-preview';previewDraft={id,title:val('announcement-title'),content:norm(val('announcement-content')),image_url:val('announcement-image-url'),announcement_type:val('announcement-type'),priority:priorityValue(val('announcement-priority')),publish_at:effectivePublishAt(),expire_at:val('announcement-expire-at')||null,is_pinned:$('announcement-is-pinned').checked,is_published:simulatePublished,product:productFromForm()};updateImagePreview();render()}
async function loadProducts(){let s=$('announcement-product-id');if(s.options.length>1)return;let r=await fetch('/api/get_output_products.php'),x=await r.json();s.innerHTML='<option value="">Velg produkt</option>'+(x.products||[]).map(p=>`<option value="${esc(p.id)}">${esc(p.name||'Ukjent')}</option>`).join('')}
async function toggleProduct(){let on=$('announcement-product-toggle').checked;$('product-section').hidden=!on;if(on)await loadProducts();syncDraft()}
function resetProduct(){let s=$('announcement-product-id');s.selectedIndex=0;$('announcement-product-toggle').checked=false;$('product-section').hidden=true;$('announcement-discount').value='';$('announcement-max-qty').value='';$('announcement-product-expiry').value=''}
 function openNew(){editRevision+=1;lastTrigger=document.activeElement;selectedId=null;previewDraft=null;publishIntent=false;simulatePublished=true;previewEffectivePublishAt=localSqlNow();$('announcementForm').reset();$('announcement-priority').value='5';$('announcement-id').value='';resetProduct();$('announcementModalTitle').textContent='Ny sak';$('simulate-published').checked=true;new bootstrap.Modal($('announcementModal')).show();syncDraft()}
 async function edit(id){let revision=++editRevision,a=announcements.find(x=>String(x.id)===String(id));if(!a)return;if(a.product)await loadProducts();if(revision!==editRevision)return;lastTrigger=document.activeElement;selectedId=String(id);publishIntent=!!a.is_published;simulatePublished=true;$('announcementModalTitle').textContent='Rediger sak';[['title',a.title],['content',norm(a.content)],['image-url',a.image_url||''],['type',a.announcement_type||'info'],['priority',priorityValue(a.priority)],['publish-at',a.publish_at?.replace(' ','T').slice(0,16)||''],['expire-at',a.expire_at?.replace(' ','T').slice(0,16)||'']].forEach(([k,v])=>$('announcement-'+k).value=v);previewEffectivePublishAt=a.publish_at?a.publish_at.replace(' ','T').slice(0,16):localSqlNow();$('announcement-id').value=a.id;$('announcement-is-pinned').checked=!!a.is_pinned;resetProduct();if(a.product){$('announcement-product-toggle').checked=true;$('product-section').hidden=false;$('announcement-product-id').value=a.product.output_product_id;$('announcement-discount').value=a.product.discount_percent||0;$('announcement-max-qty').value=a.product.max_quantity||'';$('announcement-product-expiry').value=a.product.expiry_date||''}previewDraft=null;$('simulate-published').checked=true;syncDraft();new bootstrap.Modal($('announcementModal')).show()}
 function setSaveBusy(busy){if(saveBusy===busy)return;saveBusy=busy;let form=$('announcementForm');form.setAttribute('aria-busy',String(busy));form.querySelectorAll('input,select,textarea,button').forEach(control=>{if(busy){control.dataset.saveWasDisabled=control.disabled?'1':'0';control.disabled=true}else{control.disabled=control.dataset.saveWasDisabled==='1';delete control.dataset.saveWasDisabled}})}
 async function saveAnnouncement(publish){if(saveBusy||!$('announcementForm').reportValidity())return;publishIntent=!!publish;syncDraft();let id=val('announcement-id'),existing=announcements.find(a=>String(a.id)===String(id)),data={id:id||undefined,title:val('announcement-title').trim(),content:norm(val('announcement-content')).trim(),image_url:val('announcement-image-url').trim()||null,announcement_type:val('announcement-type'),priority:priorityValue(val('announcement-priority')),is_published:publishIntent,is_pinned:$('announcement-is-pinned').checked,publish_at:effectivePublishAt(),expire_at:val('announcement-expire-at')||null,product:productFromForm()};setSaveBusy(true);try{let r=await fetch(id?'/api/update_announcement.php':'/api/create_announcement.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),x;try{x=await r.json()}catch(e){x={success:false,message:'Ugyldig svar fra server'}}if(!r.ok||!x.success){alert(x.message||'Kunne ikke lagre');return}loadRevision+=1;let saved={...(existing||{}),...data,id:id||x.announcement_id,clicks:Number(existing?.clicks)||0,created_at:existing?.created_at||new Date().toISOString(),updated_at:new Date().toISOString()};if(existing)announcements=announcements.map(a=>String(a.id)===String(id)?saved:a);else announcements.push(saved);setSaveBusy(false);bootstrap.Modal.getInstance($('announcementModal')).hide()}catch(e){alert('Kunne ikke lagre. Kontroller forbindelsen og prøv igjen.')}finally{setSaveBusy(false)}}
async function load(){let revision=++loadRevision;try{let x=await (await fetch('/api/get_announcements.php?show_unpublished=true')).json();if(revision!==loadRevision)return;if(x.success){announcements=x.announcements.map(a=>({...a,priority:priorityValue(a.priority),clicks:Number(a.clicks)||0}));render()}}catch(e){if(revision===loadRevision)$('news-preview').innerHTML='<div class="news-empty">Kunne ikke hente nyhetene. Prøv igjen.</div>'}}
async function action(action,id){let endpoint=action==='pin'?'/api/toggle_announcement_pin.php':action==='publish'?'/api/toggle_announcement_publish.php':'/api/delete_announcement.php';if(action==='delete'&&!confirm('Slette denne saken?'))return;try{let r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})}),x=await r.json();if(!r.ok||!x.success)return;loadRevision+=1;let item=announcements.find(a=>String(a.id)===String(id));if(action==='delete')announcements=announcements.filter(a=>String(a.id)!==String(id));else if(action==='pin'&&item)item.is_pinned=!item.is_pinned;else if(action==='publish'&&item){item.is_published=!item.is_published;if(item.is_published)item.publish_at=new Date().toISOString().slice(0,19).replace('T',' ')}render()}catch(e){alert('Endringen kunne ikke lagres. Prøv igjen.')}}
['announcement-title','announcement-content','announcement-image-url','announcement-type','announcement-priority','announcement-publish-at','announcement-expire-at','announcement-is-pinned','announcement-product-id','announcement-discount','announcement-max-qty','announcement-product-expiry'].forEach(id=>$(id).addEventListener('input',syncDraft));['announcement-type','announcement-priority','announcement-is-pinned','announcement-product-id','announcement-product-toggle','announcement-publish-at','announcement-expire-at','simulate-published'].forEach(id=>$(id).addEventListener('change',id==='announcement-product-toggle'?toggleProduct:id==='simulate-published'?()=>{simulatePublished=$('simulate-published').checked;syncDraft()}:syncDraft));
 $('announcementModal').addEventListener('hide.bs.modal',e=>{if(saveBusy)e.preventDefault()});
 $('announcement-image-preview').addEventListener('error',()=>{imagePreviewFailed=true;$('announcement-image-preview').hidden=true;$('announcement-image-placeholder').hidden=false});$('newAnnouncementButton').addEventListener('click',openNew);$('refreshAnnouncements').addEventListener('click',load);$('desktopView').addEventListener('click',()=>{previewMode='desktop';render()});$('mobileView').addEventListener('click',()=>{previewMode='mobile';render()});$('news-filter').addEventListener('change',renderManagement);$('saveDraftButton').addEventListener('click',()=>saveAnnouncement(false));$('publishButton').addEventListener('click',()=>saveAnnouncement(true));$('news-management').addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='edit')edit(b.dataset.id);else action(b.dataset.action,b.dataset.id)});$('announcementModal').addEventListener('hidden.bs.modal',()=>{let focusId=selectedId;previewDraft=null;previewEffectivePublishAt=null;selectedId=null;render();if(focusId)document.querySelector(`[data-story-id="${CSS.escape(String(focusId))}"] .story-content`)?.focus();else lastTrigger?.focus()});document.addEventListener('shown.bs.tab',e=>{if(e.target.dataset.bsTarget==='#content-announcements')load()});load();
})();
</script>